from sympy.physics.hep.gamma_matrices import GammaMatrix as G, LorentzIndex, kahane_simplify
from sympy.tensor.tensor import tensor_indices
mu, rho, sigma, tau = tensor_indices('mu rho sigma tau', LorentzIndex)
for prefix in ([], [rho], [rho, sigma], [rho, sigma, tau]):
    for suffix in ([], [tau] if tau not in prefix else []):
        expression = G(mu)*G(-mu)
        expected = 4
        for index in reversed(prefix):
            expression = G(index)*expression
        for index in prefix:
            expected *= G(index)
        for index in suffix:
            expression *= G(index)
            expected *= G(index)
        if prefix or suffix:
            assert kahane_simplify(expression).equals(expected)
print('Leading-matrix order checks passed')
